package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.sql.Timestamp;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Native candidate headers only; none grants dispatch permission. */
class WorkerCandidatePageTest {
    GenerationJdbcStoreTest f;JdbcWorkerState service;Instant now;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(int count){f=database();f.fixture();if(f.source instanceof org.h2.jdbcx.JdbcDataSource)f.jdbc.execute("CREATE ALIAS HEX FOR 'com.lianxibu.site.service.jobs.ResultJdbcStoreTest.hex'");service=new JdbcWorkerState(f.source);now=f.clock.instant().truncatedTo(ChronoUnit.MICROS);var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.execute(s->{var records=new JdbcJobRecords(f.source);for(int n=0;n<count;n++){String label=String.format(Locale.ROOT,"fictional-page-%03d",n),root="root-"+label,intent="intent-"+label,key="key-"+label;records.ensureIntent(new JdbcJobRecords.Intent(intent,key,1,"news_value",LocalDate.of(2026,1,1)),now);records.createRoot(new JdbcJobRecords.Root(root,intent,key,1,0,"news_value",n%14+1),now);records.prepareAttempt(new JdbcJobRecords.Attempt("attempt-"+label,root,1,"{\"fictional_request\":"+n+"}",root,"a".repeat(64)),now);f.jdbc.update("UPDATE jobs SET state='queued',eligible_at=? WHERE id=?",Timestamp.from(now.minusSeconds(n%3)),root);}return null;});}
    <T>T read(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.setReadOnly(true);return tx.execute(s->work.get());}
    JdbcWorkerState.CandidatePage page(JdbcWorkerState.CandidateCursor cursor,int limit){return read(()->service.candidatePage(now,cursor,limit));}
    @Test void Actual103CandidatesPageInOriginalFourKeyOrderWithoutLossOrDuplicates(){setup(103);var expected=read(()->service.candidates(now)).stream().map(p->p.root()).toList();var actual=new ArrayList<String>();JdbcWorkerState.CandidateCursor cursor=null;int pages=0;do{var next=page(cursor,17);assertTrue(next.rows().size()<=17);assertEquals(next.hasMore(),next.nextCursor()!=null);actual.addAll(next.rows().stream().map(p->p.root()).toList());cursor=next.nextCursor();pages++;assertThrows(UnsupportedOperationException.class,()->next.rows().clear());}while(cursor!=null);assertEquals(7,pages);assertEquals(expected,actual);assertEquals(103,new HashSet<>(actual).size());assertEquals(0,f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(0,f.count("target_type IN ('worker_claim','worker_send')"));}
    @Test void NativeStatesNextAttemptAndEligibilityFilterWhileChangedFactsAreReadAgain(){setup(6);f.jdbc.update("UPDATE jobs SET state='blocked' WHERE id='root-fictional-page-000'");f.jdbc.update("UPDATE jobs SET state='running' WHERE id='attempt-fictional-page-001'");f.jdbc.update("UPDATE jobs SET call_count=3 WHERE id='root-fictional-page-002'");f.jdbc.update("UPDATE jobs SET eligible_at=? WHERE id='root-fictional-page-003'",Timestamp.from(now.plusSeconds(1)));assertEquals(List.of("root-fictional-page-004","root-fictional-page-005"),page(null,50).rows().stream().map(p->p.root()).toList());f.jdbc.update("UPDATE jobs SET state='waiting_retry',revision=revision+1 WHERE id='root-fictional-page-004'");assertEquals("waiting_retry",page(null,50).rows().getFirst().rootState());assertEquals(1,page(null,50).rows().getFirst().revision());}
    @Test void OversizeNativeRequestIsNullAndNeverTruncatedIntoANewRequest(){setup(2);String oversized="\""+"x".repeat(1048577)+"\"";f.jdbc.update("UPDATE jobs SET request_json=? WHERE id='attempt-fictional-page-000'",oversized);String original=f.jdbc.queryForObject("SELECT request_json FROM jobs WHERE id='attempt-fictional-page-001'",String.class);var actual=page(null,50);assertEquals(2,actual.rows().size());assertNull(actual.rows().getFirst().request());assertEquals(original,actual.rows().getLast().request());assertEquals(oversized,f.jdbc.queryForObject("SELECT request_json FROM jobs WHERE id='attempt-fictional-page-000'",String.class));assertEquals(0,f.count("target_type IN ('worker_claim','worker_send')"));}
    @Test void NoTransactionWriterBadBoundsAndCursorCannotGrantAnyPermission(){setup(1);assertThrows(RuntimeException.class,()->service.candidatePage(now,null,50));var writer=new TransactionTemplate(new DataSourceTransactionManager(f.source));assertThrows(RuntimeException.class,()->writer.execute(s->service.candidatePage(now,null,50)));for(int limit:List.of(0,51))assertThrows(RuntimeException.class,()->page(null,limit));assertThrows(RuntimeException.class,()->read(()->service.candidatePage(null,null,50)));assertThrows(RuntimeException.class,()->new JdbcWorkerState.CandidateCursor(0,now,"fictional-root","fictional-attempt"));assertThrows(RuntimeException.class,()->new JdbcWorkerState.CandidateCursor(1,now,"x".repeat(65),"fictional-attempt"));assertNull(page(null,50).nextCursor());}
}
